import numpy as np

def process_grid(grid):
    """
    Transform frames:
    1. Identify rectangular frames (1s forming boundary)
    2. For each frame, shift its interior (cells inside boundary) by 1 down and 1 right
    3. Fill the shifted interior with 3s, but the very center stays 0
    4. Create a 2-border outside the frame
    """
    h, w = grid.shape
    result = np.zeros_like(grid, dtype=int)

    # Find all rectangular frames
    frames = []
    visited = np.zeros_like(grid, dtype=bool)

    for r in range(h):
        for c in range(w):
            if grid[r, c] == 1 and not visited[r, c]:
                visited[r, c] = True
                # Find frame bounds
                r_min, r_max = r, r
                c_min, c_max = c, c

                # Scan right for bottom boundary
                for cr in range(r, h):
                    if grid[cr, c] == 1:
                        r_max = cr
                    else:
                        break
                # Scan down for right boundary
                if r_max < h:
                    for cc in range(c, w):
                        if grid[r_max, cc] == 1:
                            c_max = cc
                        else:
                            break

                # Verify it's a rectangular frame
                is_frame = True
                for cr in range(r_min, r_max + 1):
                    for cc in range(c_min, c_max + 1):
                        if (cr == r_min or cr == r_max or cc == c_min or cc == c_max):
                            if grid[cr, cc] != 1:
                                is_frame = False
                                break
                    if not is_frame:
                        break
                if not is_frame:
                    continue

                # Check interior for holes (0s)
                holes = []
                for cr in range(r_min + 1, r_max):
                    for cc in range(c_min + 1, c_max):
                        if grid[cr, cc] == 0:
                            holes.append((cr, cc))
                holes = list(set(holes))

                # Check if adjacent
                holes_adjacent = False
                for i in range(len(holes)):
                    for j in range(i + 1, len(holes)):
                        r1, r2 = holes[i][0], holes[j][0]
                        c1, c2 = holes[i][1], holes[j][1]
                        if abs(r1 - r2) + abs(c1 - c2) <= 1:
                            holes_adjacent = True
                            break
                    if holes_adjacent:
                        break

                # Check if multi-row
                is_multi_row = (c_max - c_min) >= 2
                # Check if multi-col
                is_multi_col = (r_max - r_min) >= 2

                frames.append((r_min, r_max, c_min, c_max, holes, is_frame))
        visited = np.zeros_like(grid, dtype=bool)

